function spreadPeople(sc){const placed=[],steps=[[44,0],[-44,0],[0,34],[44,34],[-44,34],[0,-34],[88,0],[-88,0],[88,34],[-88,34]];for(const e of sc.entities){if(e.type!=='npc'&&e.type!=='fixture')continue;if(placed.some(o=>dist(o,e)<36)){const ok=(x,y)=>x>12&&y>20&&x<sc.w-12&&y<sc.h-8&&!placed.some(o=>Math.hypot(o.x-x,o.y-y)<36)&&!sc.entities.some(o=>o.type==='portal'&&Math.hypot(o.x-x,o.y-y)<30)&&((!sc.tilemap&&!sc.walkmask)||ARPIA_TILEMAP.standable(sc,x,y));const st=steps.find(([dx,dy])=>ok(e.x+dx,e.y+dy));if(st){e.x+=st[0];e.y+=st[1];}}placed.push(e);}}
