function changeScene(id,spawn){if(!s)return;const denied=window.ARPIA_STORY_GATES?.allowTravel(s,id)||window.ARPIA_DIVE?.allowTravel(s,id);if(denied){toast(denied);return;}const prevScene=s.scene;scene=getScene(id);const legacyTile=scene.tilemap&&s.mapRev!==2&&s.scene===id;s.scene=scene.id;let p=legacyTile?scene.nodes[0]:spawn||(prevScene!==scene.id?scene.nodes[0]:[s.x,s.y]);if(!scene.tilemap&&(p[0]<0||p[1]<0||p[0]>scene.w||p[1]>scene.h))p=scene.nodes[0];if(scene.tilemap||scene.walkmask){const q=ARPIA_TILEMAP.nearest(scene,{x:p[0],y:p[1]},120);p=q?[q.x,q.y]:scene.nodes[0];}s.mapRev=2;s.x=p[0];s.y=p[1];route=[];pending=null;camera={x:s.x,y:s.y};MOTION.reset(s);WILD.enter(s,scene);exitLock=true;if(!s.discovered.includes(id))s.discovered.push(id);if(scene.bg)img(scene.bg);$('location').textContent=scene.name;$('area-toast').textContent=scene.name;$('area-toast').classList.add('show');clearTimeout(areaTimer);areaTimer=setTimeout(()=>$('area-toast').classList.remove('show'),2200);save();updateHUD();}
function updateHUD(){if(!s)return;window.ARPIA_DIVE?.renderHUD(s);$('player-name').textContent=s.name;$('player-level').textContent='Lv. '+s.level+' · '+rankName(s.level);$('hp-bar').style.width=(s.hp/s.maxHp*100)+'%';$('mp-bar').style.width=(s.mp/s.maxMp*100)+'%';$('hp-text').textContent=`HP ${s.hp} / ${s.maxHp}`;$('mp-text').textContent=`MP ${s.mp} / ${s.maxMp}`;const floor=xpFloor(s.level),need=Math.max(1,xpNext(s.level)-floor);$('xp-bar').style.width=((s.xpTotal-floor)/need*100)+'%';$('gold').textContent=s.gold+' 핀';$('sp').textContent='선행 점수 '+s.sp;$('pet-status').textContent=s.pet?(s.pet2?'펫 2마리 동행':petName(1)+' 동행'):'신입생';$('hud-portrait').src=portrait('you');const q=QUESTS[s.stage];$('quest-title').textContent=q[0];$('quest-objective').textContent=window.ARPIA_CAPTURE_AUDIT?.objective(s)||(s.stage===11?`${q[1]} (${s.train}/3)`:q[1]);$('quest-tracker').classList.toggle('hidden',!!battle);$('map-mini').classList.toggle('hidden',!!battle);}
function advance(to,reward=10){if(s.stage>=to)return;s.stage=to;s.sp+=reward;s.gold+=10;save();updateHUD();chime('win');toast('미션 갱신 · '+QUESTS[to][0]);}
function talk(lines,done){route=[];pending=null;dialog={lines,i:0,done};$('dialog').classList.remove('hidden');showLine();}
function showLine(){const [raw,text]=dialog.lines[dialog.i],who=raw==='teacher'?['aron','scoll','esta'][s.element]:raw;
 document.querySelector('.mission-choice-pop')?.remove();$('dialog-next').style.display='';
 $('speaker').textContent=who==='you'?s.name:who==='narrator'?'이야기':NPC[who]?.name||who;
 const people=[...new Set(dialog.lines.map(l=>l[0]==='teacher'?['aron','scoll','esta'][s.element]:l[0]).filter(id=>id!=='you'&&id!=='narrator'&&NPC[id]))];
 const left=who!=='you'&&who!=='narrator'?who:people[0],right=people.length>1&&!dialog.lines.some(l=>l[0]==='you')?people.find(id=>id!==left):'you';
 for(const [el,id]of [[$('dialog-portrait'),left],[$('dialog-partner'),right]]){el.style.display=left?'':'none';if(id){el.src=id==='you'?heroPortrait(s.hero,window.ARPIA_HERO_ART?.emotion(text,who)||'neutral'):portrait(id);el.dataset.emotion=id==='you'?(window.ARPIA_HERO_ART?.emotion(text,who)||'neutral'):'neutral';el.alt=id==='you'?s.name:NPC[id]?.name||'';el.classList.toggle('inactive',id!==who);}}
 $('dialog-text').textContent=text.replaceAll('{name}',s.name).replaceAll('{element}',ELS[s.element]).replaceAll('{spell}',SPELLS[s.element]);$('dialog-next').firstChild.textContent=dialog.i===dialog.lines.length-1?'마치기 ':'계속 ';chime();}
function nextLine(){if(!dialog||document.querySelector('.mission-choice-pop'))return;dialog.i++;if(dialog.i<dialog.lines.length)showLine();else{const fn=dialog.done;dialog=null;$('dialog').classList.add('hidden');fn?.();save();updateHUD();}}
function missionOffer(title,giver,description,onAccept,acceptLabel="미션받기"){talk([[giver,description]]);$('dialog-next').style.display='none';const box=document.createElement('div');box.className='mission-choice-pop';box.innerHTML=`<strong>${title}</strong><button data-choice="accept">${acceptLabel}</button><button data-choice="exit">나가기</button>`;$('dialog').appendChild(box);box.querySelector('[data-choice="accept"]').onclick=()=>{box.remove();$('dialog-next').style.display='';dialog.done=onAccept;nextLine();};box.querySelector('[data-choice="exit"]').onclick=()=>{box.remove();$('dialog-next').style.display='';dialog.done=null;nextLine();};box.querySelector('[data-choice="accept"]').focus();}
