 if(e.id==='bread')return talk([['narrator','식당에는 갓 구운 빵 냄새가 은은하게 퍼진다. 잠깐 쉬며 기운을 회복했다.']],()=>{s.hp=s.maxHp;s.mp=s.maxMp;});
 if(e.id==='george'&&q===0)return talk(D.george,()=>advance(1));
