function nearestNode(p){let best=0,d=Infinity;scene.nodes.forEach(([x,y],i)=>{const nd=Math.hypot(x-p.x,y-p.y);if(nd<d){d=nd;best=i;}});return best;}
function projectPoint(p){if(scene.tilemap||scene.walkmask){const q=ARPIA_TILEMAP.nearest(scene,p)||{x:s.x,y:s.y};return{...q,d:dist(p,q)};}let best={x:scene.nodes[0][0],y:scene.nodes[0][1]},bd=Infinity;for(const[a,b]of scene.edges){const A=scene.nodes[a],B=scene.nodes[b],dx=B[0]-A[0],dy=B[1]-A[1];const t=clamp(((p.x-A[0])*dx+(p.y-A[1])*dy)/(dx*dx+dy*dy),0,1);const q={x:A[0]+t*dx,y:A[1]+t*dy},d=dist(p,q);if(d<bd){bd=d;best=q;}}return{...best,d:bd};}
function pathTo(p,entity=null){if(scene.tilemap||scene.walkmask){route=ARPIA_TILEMAP.plan(scene,s,entity?{x:entity.x,y:entity.y+6}:p);if(!route.length){pending=null;if(!entity)toast('그곳으로 이어지는 길이 없습니다.');return;}}else{const start=nearestNode(s),end=nearestNode(p),dd=scene.nodes.map(()=>Infinity),prev=[],seen=new Set;dd[start]=0;while(seen.size<scene.nodes.length){let u=-1;for(let i=0;i<dd.length;i++)if(!seen.has(i)&&(u===-1||dd[i]<dd[u]))u=i;if(u===end||!Number.isFinite(dd[u]))break;seen.add(u);for(const[a,b]of scene.edges){const v=a===u?b:b===u?a:-1;if(v<0)continue;const w=Math.hypot(scene.nodes[u][0]-scene.nodes[v][0],scene.nodes[u][1]-scene.nodes[v][1]);if(dd[u]+w<dd[v]){dd[v]=dd[u]+w;prev[v]=u;}}}let indices=[end];while(indices[0]!==start&&prev[indices[0]]!==undefined)indices.unshift(prev[indices[0]]);route=indices.map(i=>({x:scene.nodes[i][0],y:scene.nodes[i][1]}));const proj=projectPoint(p);route.push({x:entity?p.x:proj.x,y:entity?p.y:proj.y});if(route.length>2&&dist(s,route[1])<dist(route[0],route[1]))route.shift();}// Stop at conversational distance instead of standing on the NPC's feet.
if(entity&&entity.type==='npc'){
 while(route.length&&dist(route.at(-1),entity)<29)route.pop();
 const approach=route.at(-1)||s,d=dist(approach,entity);
 if(d>29)route.push({x:entity.x+(approach.x-entity.x)*29/d,y:entity.y+(approach.y-entity.y)*29/d});
 else route.push({x:s.x,y:s.y});
}pending=entity;}
